/**
 * @file verilator_hooked.h
 * @brief Interface between the C++ exchange node and the Verilator RTL.
 *
 * This header provides a thin wrapper around the Verdilated Vspread_detector
 * module. The real Vspread_detector C++ classes are generated by Verilator
 * from hardware/rtl/spread_detector.sv via CMake's `verilate()` command.
 *
 * Usage:
 *   #include "verilator_hooked.h"
 *   Vspread_detector fpga;   // zero-init is required
 *   fpga.clk = 0;
 *   fpga.rst_n = 0;
 *   fpga.s_axis_tdata = spread;
 *   fpga.s_axis_tvalid = 1;
 *   fpga.eval();  // positive edge
 *   fpga.eval();  // negative edge
 *   if (fpga.threshold_breached_o) { ... }
 */

#pragma once

#include <cmath>
#include <cstdint>

#include "config.h"

// The Verilated class is the base class for all Verilated modules.
struct Verilated {
    virtual ~Verilated() = default;
    virtual void eval() = 0;
};

// Minimal RTL signal wrapper matching spread_detector.sv:
//   module spread_detector #(
//       parameter DATA_WIDTH = 32,
//       parameter THRESHOLD  = 50
//   )(
//       input  logic clk,
//       input  logic rst_n,
//       input  logic [DATA_WIDTH-1:0] s_axis_tdata,
//       input  logic s_axis_tvalid,
//       output logic s_axis_tready,
//       output logic threshold_breached_o,
//       output logic [DATA_WIDTH-1:0] current_spread_o
//   );
struct Vspread_detector : Verilated {
    // Clock & reset
    int clk;
    int rst_n;

    // AXI-Stream slave input
    int s_axis_tvalid;
    int s_axis_tready;
    int32_t s_axis_tdata;

    // Output signal
    int threshold_breached_o;
    int32_t current_spread_o;

    Vspread_detector() {
        clk = 0;
        rst_n = 0;
        s_axis_tvalid = 0;
        s_axis_tready = 0;
        s_axis_tdata = 0;
        threshold_breached_o = 0;
        current_spread_o = 0;
    }

    void eval() override {
        // Mock RTL evaluation: compute threshold breach from s_axis_tdata.
        // Z-score * 1e8 is fed to RTL; threshold_breached_o fires when
        // |s_axis_tdata| >= threshold_scaled.
        const int32_t threshold = Config{}.threshold_scaled;
        threshold_breached_o = (std::abs(s_axis_tdata) >= threshold) ? 1 : 0;
    }
};
